import numpy as np
W = {k: v.astype(np.float64) for k, v in np.load('weights.npz').items()}
d, H, hd = 384, 6, 64
rng = np.random.default_rng(7)

def centered_gram(A, side):
    # side='in': A^T A (residual-space read structure); side='out': A A^T (residual-space write structure)
    G = A.T @ A if side == 'in' else A @ A.T
    G = G - np.trace(G) / G.shape[0] * np.eye(G.shape[0])
    return G / np.linalg.norm(G)

mats = {}
for l in range(4):
    for nm in ['W_q', 'W_k', 'W_v', 'W_fc']:
        mats[(f'{nm}.{l}', 'read')] = centered_gram(W[f'{nm}.{l}'], 'in')
    for nm in ['W_o', 'W_proj']:
        mats[(f'{nm}.{l}', 'write')] = centered_gram(W[f'{nm}.{l}'], 'out')

# null for the Frobenius inner product of two independent centered Grams: simulate
def null_sd(shapeA, sideA, shapeB, sideB, n=200):
    vals = []
    for _ in range(n):
        A = rng.standard_normal(shapeA); B = rng.standard_normal(shapeB)
        vals.append(np.sum(centered_gram(A, sideA) * centered_gram(B, sideB)))
    return np.mean(vals), np.std(vals)

keys = list(mats)
shapes = {k: W[k[0]].shape for k in keys}
cache = {}
res = []
for i in range(len(keys)):
    for j in range(i + 1, len(keys)):
        a, b = keys[i], keys[j]
        sig = (shapes[a], a[1], shapes[b], b[1])
        if sig not in cache:
            cache[sig] = null_sd(shapes[a], 'in' if a[1] == 'read' else 'out', shapes[b], 'in' if b[1] == 'read' else 'out', n=100)
        m, s = cache[sig]
        v = np.sum(mats[a] * mats[b])
        res.append(((v - m) / s, a[0], b[0]))
zs = np.array([r[0] for r in res])
print(f'{len(res)} pairwise residual-space Gram alignments (read/write subspaces of all matrices)')
print(f'z-scores: mean={zs.mean():+.3f} sd={zs.std():.3f} max|z|={np.abs(zs).max():.2f}  #|z|>3: {(np.abs(zs)>3).sum()}')
for r in sorted(res, key=lambda r: -abs(r[0]))[:8]:
    print(f'   z={r[0]:+.2f}  {r[1]} vs {r[2]}')

# Per-head circuits: QK trace (same-token / positional bias) and OV trace (copying), Frobenius alignment of Wq_h and Wk_h
print()
print('Per-head QK trace z  (tr(Wq_h^T Wk_h) / null sd) and OV trace z (tr(Wo_h Wv_h) / null sd):')
for l in range(4):
    qk, ov = [], []
    for h in range(H):
        s = slice(h * hd, (h + 1) * hd)
        Wq, Wk, Wv, Wo = W[f'W_q.{l}'][s], W[f'W_k.{l}'][s], W[f'W_v.{l}'][s], W[f'W_o.{l}'][:, s]
        t_qk = np.sum(Wq * Wk); sd_qk = 0.02 * 0.02 * np.sqrt(hd * d)
        t_ov = np.trace(Wo @ Wv); sd_ov = 0.02 * 0.0070711 * np.sqrt(hd * d)
        qk.append(t_qk / sd_qk); ov.append(t_ov / sd_ov)
    print(f'  layer {l}: QK z = {np.round(qk, 2)}   OV z = {np.round(ov, 2)}')

# Privileged-basis test: do residual dimensions have consistent norms across matrices (Adam / LN effects)?
print()
cols = []
names = []
for l in range(4):
    for nm in ['W_q', 'W_k', 'W_v', 'W_fc']:
        cols.append(np.linalg.norm(W[f'{nm}.{l}'], axis=0)); names.append(f'{nm}.{l} in')
    for nm in ['W_o', 'W_proj']:
        cols.append(np.linalg.norm(W[f'{nm}.{l}'], axis=1)); names.append(f'{nm}.{l} out')
C = np.corrcoef(np.array(cols))
off = C[np.triu_indices(len(cols), 1)]
print(f'Correlation of per-residual-dimension norms across {len(cols)} matrices: mean={off.mean():+.4f} sd={off.std():.4f} (null sd ~ {1/np.sqrt(d):.4f}), max={off.max():+.3f}, min={off.min():+.3f}')
cv = [c.std() / c.mean() for c in cols]
print('Coefficient of variation of residual-dim norms (null ~ 1/sqrt(2*n_rows)):')
for n, c, colv in zip(names, cols, cv):
    pass
for l in range(4):
    print('  ', ' '.join(f'{names[l*6+i]}={cv[l*6+i]:.4f}' for i in range(6)))
print('   null: 384-row matrices ~', round(1/np.sqrt(2*384), 4), ' 1536-row ~', round(1/np.sqrt(2*1536), 4))

